/**
 * Reading and writing the word registry files (shared by the words:* scripts).
 *
 *   src/data/lexicon/word-registry.json  ← edited by humans (and by the scripts)
 *   src/data/lexicon/word-usage.json     ← generated by `npm run words:sync`, never edit
 *
 * See docs/WORD-REGISTRY.md for what each field means.
 */
import fs from 'node:fs'
import path from 'node:path'
import * as prettier from 'prettier'
import { ROOT } from './collect-words.mjs'

export const REGISTRY_FILE = path.join(ROOT, 'src/data/lexicon/word-registry.json')
export const USAGE_FILE = path.join(ROOT, 'src/data/lexicon/word-usage.json')

/** Allowed values of the "audio" field. */
export const AUDIO_STATES = ['missing', 'recorded']

const REGISTRY_ABOUT =
  'One entry per Benga word. The key on the left comes from the word (src/utils/audioId.js); ' +
  'never type it by hand. Edit livingDictionaryId, audio, audioFile and notes here, or at ' +
  'http://localhost:8080/admin/palabras while `npm run serve` is running. ' +
  'After adding content run `npm run words:sync`. Guide: docs/WORD-REGISTRY.md'

const USAGE_ABOUT =
  'GENERATED by `npm run words:sync`. Do not edit: changes are overwritten. ' +
  'Shows, for every word key, how it is spelled and in which files it appears.'

/** A complete entry, in a fixed field order, with defaults for missing fields. */
export function normaliseEntry(entry = {}) {
  return {
    word: entry.word || '',
    livingDictionaryId: entry.livingDictionaryId || null,
    audio: AUDIO_STATES.includes(entry.audio) ? entry.audio : 'missing',
    audioFile: entry.audioFile || null,
    notes: entry.notes || ''
  }
}

export function loadRegistry() {
  if (!fs.existsSync(REGISTRY_FILE)) return {}
  const content = JSON.parse(fs.readFileSync(REGISTRY_FILE, 'utf8'))
  return content.words || {}
}

function sortByKey(object) {
  return Object.fromEntries(
    Object.keys(object)
      .sort((a, b) => a.localeCompare(b, 'es'))
      .map((key) => [key, object[key]])
  )
}

async function writeJson(file, data) {
  const options = (await prettier.resolveConfig(file)) || {}
  // Start from an indented layout so Prettier keeps one field per line (easier to read and diff).
  const text = await prettier.format(JSON.stringify(data, null, 2), { ...options, parser: 'json' })
  fs.mkdirSync(path.dirname(file), { recursive: true })
  fs.writeFileSync(file, text)
}

export async function saveRegistry(words) {
  const normalised = {}
  for (const [key, entry] of Object.entries(words)) normalised[key] = normaliseEntry(entry)
  await writeJson(REGISTRY_FILE, { _about: REGISTRY_ABOUT, words: sortByKey(normalised) })
}

export async function saveUsage(usage) {
  await writeJson(USAGE_FILE, { _about: USAGE_ABOUT, words: sortByKey(usage) })
}

export function relative(file) {
  return path.relative(ROOT, file).replace(/\\/g, '/')
}
